scenario('actual reservation task keeps exclusive one-shot semantics using only fake filesystem IO', () => {
  const source = fs.readFileSync(path.join(root, 'cypress.shipping.config.cjs'), 'utf8');
  for (const failure of [null, { stage: 'mkdir', code: 'EACCES' },
    { stage: 'write', code: 'EEXIST' }, { stage: 'write', code: 'EACCES' }]) {
    const calls = [], exported = { exports: {} };
    let task;
    const fakeFs = {
      mkdirSync(target, options) {
        calls.push('mkdir');
        same(target, path.join(root, '.publication/private/sq01-live-2026-11-18'), 'Reservation stays in project-private directory');
        same(clone(options), { recursive: true }, 'Directory preparation remains recursive');
        if (failure?.stage === 'mkdir') throw Object.assign(Error(secret), { code: failure.code });
      },
      writeFileSync(target, data, options) {
        calls.push('write');
        same(target, path.join(root, '.publication/private/sq01-live-2026-11-18/run-reserved.json'), 'The actual one-shot latch path is unchanged');
        same(clone(options), { flag: 'wx' }, 'Existing latch cannot be overwritten');
        const record = JSON.parse(data);
        same(Object.keys(record).sort(), ['automaticTriggersIncluded', 'quoteLimit', 'reservedAt', 'retryAllowed'], 'Reservation writes only expected safe fields');
        same(record.quoteLimit, 1, 'Automatic and manual requests share one permitted quote');
        same(record.automaticTriggersIncluded, true, 'Automatic triggers remain included');
        same(record.retryAllowed, false, 'Reservation grants no retry');
        check(typeof record.reservedAt === 'string' && Number.isFinite(Date.parse(record.reservedAt)), 'The reservation timestamp is a valid timestamp');
        if (failure?.stage === 'write') throw Object.assign(Error(secret), { code: failure.code });
      }
    };
    const context = vm.createContext({ module: exported, __dirname: root,
      require(specifier) {
        if (specifier === 'node:fs') return fakeFs;
        if (specifier === 'node:path') return path;
        same(specifier, './cypress.authenticated.config.cjs', 'No other config dependency can perform IO');
        return { e2e: {} };
      } });
    vm.runInContext(source, context, { filename: 'cypress.shipping.config.cjs', timeout: 1000 });
    const config = exported.exports;
    same(config.retries, 0, 'Config still prohibits automatic test retries');
    same(config.watchForFileChanges, false, 'File watching cannot restart the one-shot slice');
    config.e2e.setupNodeEvents((name, handlers) => {
      same(name, 'task', 'Only the expected task handler is installed');
      same(Object.keys(handlers), ['sq01ReserveRun'], 'No unrelated task is introduced');
      task = handlers.sq01ReserveRun;
    });
    check(typeof task === 'function', 'The actual reservation task is captured');
    const result = clone(task());
    const expected = failure ? { reserved: false, reasonCode: failure.code === 'EEXIST'
      ? 'SHIPPING_RUN_ALREADY_RESERVED' : 'SHIPPING_RESERVATION_UNAVAILABLE' } : { reserved: true };
    same(result, expected, 'Actual task reports safe success or a fixed failure reason');
    same(calls, failure?.stage === 'mkdir' ? ['mkdir'] : ['mkdir', 'write'], 'No unexpected filesystem operation occurs');
    check(!JSON.stringify(result).includes(secret), 'Filesystem error details cannot escape the task');
  }
});

for (const reasonCode of ['SHIPPING_RUN_ALREADY_RESERVED', 'SHIPPING_RESERVATION_UNAVAILABLE']) {
  scenario('stub reservation failure is recorded: ' + reasonCode, () => {
    const h = harness({ reservation: { reserved: false, reasonCode } });
    same(h.setupError()?.code, reasonCode, 'Task failure cannot proceed as a successful reservation');
    same(h.rejections().firstRejection.reasonCode, reasonCode, 'Reservation reason is sanitized and published');
    same(h.rejections().firstRejection.source, 'reservation', 'Reservation is distinguished from outgoing mutation');
    same(h.status().shipping.count, 0, 'Rejected reservation makes no request');
    same(h.reservationCalls(), 1, 'Only an in-memory task stub was invoked');
    privacy(h.status());
  });
}

scenario('unknown diagnostic fields and codes cannot export private canaries', () => {
  const { createGuardDiagnostics } = require('../cypress/support/shipping-guard-diagnostics.cjs');
  const log = createGuardDiagnostics();
  log.record({ reasonCode: 'SHIPPING_' + secret, operation: secret, source: secret, phase: secret,
    quoteCount: secret, recipient_name: secret, request: { body: secret }, error: new Error(secret) });
  const snapshot = log.snapshot();
  same(snapshot.firstRejection.reasonCode, 'SHIPPING_UNCLASSIFIED_GUARD_REJECTION', 'Unknown code maps to fixed fallback');
  same(snapshot.firstRejection.operation, 'unknown', 'Unknown operation is not copied');
  privacy(snapshot);
});

// Same fixtures are evaluated against the exact archived guard. This proves
// agreement only for this finite matrix, not every possible browser/request.
const decisions = [
  ['first intended quote', (h) => h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted],
  ...matrix.map(([name, _code, mutate]) => [name, h => { const body = h.body(); mutate(body, h); return h.dispatch(h.request('/api/v1/shipping/quote', body)).permitted; }]),
  ['checkout POST', h => h.dispatch(h.request('/api/v1/checkout', h.body())).permitted],
  ['external write', h => h.dispatch(h.request('https://example.invalid/' + secret, { private: secret })).permitted],
  ['unreviewed mutation', h => h.dispatch(h.request('/api/v1/customer/private/' + secret, { private: secret })).permitted],
  ['second quote', h => { h.dispatch(h.request('/api/v1/shipping/quote', h.body())); return h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted; }],
  ['unarmed destination', h => h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted, { arm: false }],
  ['postal was not last', h => h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted,
    { edits: ['name', 'tel', 'postal-code', 'street-address'] }],
  ['untrusted private edit', h => h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted,
    { trusted: { name: false } }],
  ['wrong phase', h => { h.gate().phase('cleanup'); return h.dispatch(h.request('/api/v1/shipping/quote', h.body())).permitted; }],
  ['OTP retry', h => h.dispatch(h.request('/api/v1/auth/otp/start', { mobile })).permitted],
  ['additional wrong Add package', h => h.dispatch(h.request('/api/v1/cart/items', {
    product_slug: intent.slug, package_id: 64, quantity: 2 })).permitted],
  ['checkout DOM submit', h => h.submit().error === undefined]
];
for (const [name, action, readyOptions] of decisions) {
  const old = harness({ legacy: true }); old.ready(readyOptions);
  const current = harness(); current.ready(readyOptions);
  same(action(current), action(old), 'Archived/current permission parity: ' + name);
  permissionComparisons++;
}

console.log(JSON.stringify({ result: 'PASS',
  kind: 'Local synthetic VM middleware/DOM checks; not live E2E or a shipping quote',
  scenarios: scenarios.length, assertions, archivedPermissionComparisons: permissionComparisons,
  networkRequests: 0, browserRuns: 0, otpRequests: 0, liveCartMutations: 0,
  liveShippingQuotes: 0, realReservationTasks: 0, privateValuesLogged: false }));
